<script setup lang="ts">
import products from '~/data/products.json';import type {Product} from '~/data/types';const route=useRoute();const product=(products as Product[]).find(p=>p.slug===route.params.slug);if(!product)throw createError({statusCode:404,statusMessage:'Produto não encontrado'});const selectedColor=ref(product.colors[0]!);const selected=ref(product.variants[0]||'Padrão');const qty=ref(1);const cart=useCartStore();const whatsapp='https://wa.me/5583998739712?text='+encodeURIComponent('Olá! Gostaria de consultar disponibilidade e detalhes de: '+product.name);const selectedVariant=()=>`${selectedColor.value.label}${product.variants.length?` · ${selected.value}`:''}`;useSeoMeta({title:product.name+' | Tecla Nativa',description:product.summary,ogTitle:product.name+' | Tecla Nativa',ogDescription:product.summary});
</script>
<template><div class="wrap page-wrap" v-if="product"><div class="breadcrumb"><NuxtLink to="/">Início</NuxtLink><span>/</span><NuxtLink to="/produtos">Produtos</NuxtLink><span>/</span><span>{{product.name}}</span></div><div class="product-detail"><div class="detail-image"><img :src="selectedColor.image" :alt="`${product.name} — ${selectedColor.label}`" width="640" height="640"/><span class="detail-image-note">Imagem conceitual gerada para a apresentação</span></div><div class="detail-copy"><span class="eyebrow">{{product.categoryLabel}}</span><h1>{{product.name}}</h1><p class="detail-summary">{{product.description}}</p><div class="detail-price">{{product.priceLabel}}</div><p class="price-note">Valor ilustrativo nesta apresentação.</p><div class="detail-color-field"><span>Cor: <b>{{selectedColor.label}}</b></span><div class="detail-color-options" role="group" :aria-label="`Cores de ${product.name}`"><button v-for="color in product.colors" :key="color.id" type="button" class="color-swatch color-swatch-large" :class="{'is-selected':selectedColor.id===color.id}" :style="{'--swatch-color':color.swatch}" :aria-label="`Selecionar cor ${color.label}`" :aria-pressed="selectedColor.id===color.id" :title="color.label" @click="selectedColor=color" /></div></div><div v-if="product.variants.length" class="variant-field"><label for="variant">Escolha uma opção</label><select id="variant" v-model="selected"><option v-for="v in product.variants" :key="v">{{v}}</option></select></div><div class="quantity-field"><label for="quantity">Quantidade</label><div><button aria-label="Diminuir quantidade" @click="qty=Math.max(1,qty-1)">−</button><input id="quantity" v-model.number="qty" type="number" min="1" max="10"/><button aria-label="Aumentar quantidade" @click="qty=Math.min(10,qty+1)">＋</button></div></div><button class="button button-dark detail-add" @click="cart.add(product,selectedVariant(),qty,selectedColor.image);navigateTo('/carrinho')">Adicionar à sacola <span>↗</span></button><a class="button button-outline detail-whatsapp" :href="whatsapp" target="_blank" rel="noopener noreferrer">Consultar pelo WhatsApp <span>↗</span></a><div class="detail-assurances"><p><span>✓</span> Compatibilidade descrita com transparência</p><p><span>✓</span> Consulte disponibilidade pelo atendimento</p><p><span>✓</span> Informações da imagem são conceituais</p></div></div></div><section class="detail-info"><div><span class="eyebrow">DETALHES DO PRODUTO</span><h2>Feito para <em>fazer sentido.</em></h2></div><div class="spec-list"><div v-for="s in product.specs" :key="s.label"><b>{{s.label}}</b><span>{{s.value}}</span></div><div><b>Compatibilidade</b><span>{{product.compatibility}}</span></div><div><b>Conteúdo da embalagem</b><span>{{product.box}}</span></div><div><b>SKU ilustrativo</b><span>{{product.sku}}</span></div></div></section><p class="catalog-disclaimer">Descrição e especificações ilustrativas. Confirme os dados do produto real antes de comprar.</p></div></template>
